import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

// Daily feed for the app (public/content-feed.json), regenerated by
// .github/workflows/daily-content-generator.yml.
//
// The model never writes religious text. It only picks references (a verse, a
// Quranic supplication, a hadith from Sahih al-Bukhari / Sahih Muslim) and writes a
// short Turkish "message of the day". The texts come from published sources:
//   - Quran: api.alquran.cloud (Uthmani script + official translations)
//   - Hadith: fawazahmed0/hadith-api (sahih collections only)
// A second model call only translates: the message, supplication titles, and the
// hadith for languages without a published translation. Every step has a fallback,
// so the feed is never empty; the app shows its bundled content when a part is missing.

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const outputPath = path.resolve(__dirname, '../public/content-feed.json');

const GEMINI_API_KEY = process.env.GEMINI_API_KEY || '';

const now = new Date();
const isFriday = now.getDay() === 5;
const dayOfYear = Math.floor((now - new Date(now.getFullYear(), 0, 0)) / 86400000);

// All app languages (lib/i18n/locales).
const APP_LANGUAGES = [
  'tr', 'en', 'ar', 'fa', 'ur', 'de', 'fr', 'es', 'it', 'ru', 'uk', 'pl', 'nl', 'pt', 'sv',
  'el', 'hu', 'bg', 'ro', 'bs', 'az', 'uz', 'kk', 'id', 'ms', 'bn', 'hi', 'zh', 'ja', 'ko',
];

// ---------------------------------------------------------------------------
// Sources
// ---------------------------------------------------------------------------

const QURAN_EDITIONS = {
  arabic: 'quran-uthmani',
  tr: 'tr.diyanet',
  en: 'en.sahih',
  id: 'id.indonesian',
  ms: 'ms.basmeih',
};

// Further app languages that have a published translation on alquran.cloud.
// Optional: a missing one only makes the app fall back to English for that language.
const OPTIONAL_QURAN_EDITIONS = {
  fa: 'fa.fooladvand', ur: 'ur.jalandhry', de: 'de.bubenheim', fr: 'fr.hamidullah',
  es: 'es.cortes', it: 'it.piccardo', ru: 'ru.kuliev', pl: 'pl.bielawskiego',
  nl: 'nl.siregar', pt: 'pt.elhayek', sv: 'sv.bernstrom', bg: 'bg.theophanov',
  ro: 'ro.grigore', bs: 'bs.korkut', az: 'az.mammadaliyev', uz: 'uz.sodik',
  bn: 'bn.bengali', hi: 'hi.hindi', zh: 'zh.jian', ja: 'ja.japanese', ko: 'ko.korean',
};

const HADITH_API = 'https://cdn.jsdelivr.net/gh/fawazahmed0/hadith-api@1/editions';
const HADITH_COLLECTIONS = ['bukhari', 'muslim']; // sahih only
const HADITH_MAX_NUMBER = 7563;
const HADITH_MAX_LENGTH = 450; // English characters; longer ones do not fit the card
// Published hadith translations used as-is. Arabic keeps its chain of narration;
// Urdu/Indonesian editions include the full chain too, so those are translated
// from the English text instead.
const HADITH_EDITIONS = { ar: 'ara', tr: 'tur', en: 'eng', fr: 'fra', ru: 'rus', bn: 'ben' };

// Used when the model fails or picks something that does not resolve.
const FALLBACK_VERSE_REFS = [
  [17, 82], [13, 28], [94, 5], [2, 186], [2, 286], [39, 53], [65, 3], [93, 3],
  [10, 57], [3, 173], [2, 153], [20, 114], [40, 60], [26, 80], [41, 44], [2, 152],
];
const FALLBACK_DUA_REFS = [
  [2, 201], [3, 8], [7, 23], [14, 40], [14, 41], [17, 24], [20, 114], [21, 87], [23, 118],
  [25, 74], [28, 24], [59, 10], [71, 28], [2, 127], [2, 250], [3, 147], [18, 10], [21, 89],
];
const FALLBACK_HADITH_REFS = [
  ['bukhari', 13], ['bukhari', 6018], ['bukhari', 6114], ['bukhari', 5027], ['bukhari', 69],
  ['bukhari', 6406], ['bukhari', 10], ['bukhari', 6011], ['bukhari', 6136], ['bukhari', 6464],
  ['bukhari', 6116], ['bukhari', 6035], ['bukhari', 6412], ['bukhari', 6094], ['bukhari', 38],
  ['bukhari', 1],
];
const FALLBACK_MESSAGES = [
  "Büyük işleri beklerken küçük hayırları ihmal etme. Rabbinin rızası, her gün kılınan vakit namazındaki ve çekilen samimi bir tesbihteki sebatta saklıdır.",
  "Dünya telaşı ruhunu daralttığında dilini zikirle, alnını secdeyle buluştur. Allah'ı anan kalp hiçbir zaman sahipsiz ve çaresiz kalmaz.",
  "Namaz, kul ile Rabbi arasındaki en mukaddes buluşmadır. Vaktini namaza göre ayarlayanın vakti de, ömrü de, hanesi de bereketlenir.",
  "İstediğin şey ne kadar büyük olursa olsun, Rabbinin kudretinden ve merhametinden daha büyük değildir. Samimiyetle iste, O icabet eder.",
];
const FRIDAY_MESSAGE =
  "Cuma gününün bereketini bol salavat, Kehf suresi tilaveti ve samimi dualarla taçlandırın. Bugün duaların geri çevrilmediği bir icabet saati gizlidir.";

const pick = (list) => list[dayOfYear % list.length];
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function fetchJson(url) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`HTTP ${res.status} ${url}`);
  return res.json();
}

async function fetchVerifiedVerse(surahNumber, verseNumber) {
  if (!Number.isInteger(surahNumber) || surahNumber < 1 || surahNumber > 114) return null;
  if (!Number.isInteger(verseNumber) || verseNumber < 1) return null;
  const editions = [...Object.values(QURAN_EDITIONS), ...Object.values(OPTIONAL_QURAN_EDITIONS)].join(',');
  try {
    const json = await fetchJson(`https://api.alquran.cloud/v1/ayah/${surahNumber}:${verseNumber}/editions/${editions}`);
    if (json.code !== 200 || !Array.isArray(json.data)) return null;
    const byEdition = Object.fromEntries(json.data.map((e) => [e.edition.identifier, e]));
    const text = (key) => byEdition[QURAN_EDITIONS[key]]?.text?.trim();
    if (Object.keys(QURAN_EDITIONS).some((key) => !text(key))) return null;
    return {
      surahNumber,
      verseNumber,
      surahName: byEdition[QURAN_EDITIONS.arabic].surah.englishName,
      arabic: text('arabic'),
      translations: {
        tr: text('tr'),
        en: text('en'),
        id: text('id'),
        ms: text('ms'),
        ...Object.fromEntries(
          Object.entries(OPTIONAL_QURAN_EDITIONS)
            .map(([lang, edition]) => [lang, byEdition[edition]?.text?.trim()])
            .filter(([, value]) => value)
        ),
      },
      textSource: 'api.alquran.cloud',
    };
  } catch (e) {
    console.warn(`⚠️ Ayet doğrulanamadı (${surahNumber}:${verseNumber}):`, e.message);
    return null;
  }
}

async function fetchVerifiedHadith(collection, number) {
  if (!HADITH_COLLECTIONS.includes(collection)) return null;
  if (!Number.isInteger(number) || number < 1 || number > HADITH_MAX_NUMBER) return null;
  const texts = {};
  for (const [lang, prefix] of Object.entries(HADITH_EDITIONS)) {
    try {
      const json = await fetchJson(`${HADITH_API}/${prefix}-${collection}/${number}.min.json`);
      const text = json?.hadiths?.[0]?.text
        ?.replace(/\s+/g, ' ')
        // The Turkish edition has OCR slips such as "Aııah" for "Allah".
        .replace(/\bA[ıiIl]{2}ah/g, 'Allah')
        .trim();
      if (text) texts[lang] = text;
    } catch {
      // optional language; English/Turkish are checked below
    }
  }
  if (!texts.en || !texts.tr || !texts.ar) return null;
  if (texts.en.length > HADITH_MAX_LENGTH) return null;
  return { collection, number, arabic: texts.ar, translations: texts, textSource: 'fawazahmed0/hadith-api' };
}

// ---------------------------------------------------------------------------
// Gemini
// ---------------------------------------------------------------------------

async function getAvailableGeminiModels() {
  try {
    const data = await fetchJson(`https://generativelanguage.googleapis.com/v1beta/models?key=${GEMINI_API_KEY}`);
    const excluded = /image|tts|transcribe|clip|audio|robotics|computer-use|deep-research/i;
    return (data.models ?? [])
      .filter((m) => m.supportedGenerationMethods?.includes('generateContent') && !excluded.test(m.name))
      .map((m) => m.name.replace(/^models\//, ''));
  } catch (e) {
    console.warn('⚠️ ListModels çağrılırken hata:', e.message);
    return [];
  }
}

let modelCandidates = null;

/** Sends a prompt, returns parsed JSON that passes `isValid`, or null. */
async function askGemini(prompt, isValid, label) {
  if (!GEMINI_API_KEY) {
    console.log(`GEMINI_API_KEY yok, ${label} için yedek kullanılacak.`);
    return null;
  }
  if (!modelCandidates) {
    const preferred = [
      'gemini-2.5-flash',
      'gemini-2.0-flash',
      'gemini-1.5-flash',
      'gemini-flash-latest',
      'gemini-flash-lite-latest',
    ];
    modelCandidates = Array.from(new Set([...preferred, ...(await getAvailableGeminiModels())])).slice(0, 8);
  }
  for (const model of modelCandidates) {
    try {
      const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${GEMINI_API_KEY}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          contents: [{ parts: [{ text: prompt }] }],
          generationConfig: { temperature: 0.4, maxOutputTokens: 32768, responseMimeType: 'application/json' },
        }),
      });
      if (!res.ok) {
        console.warn(`⚠️ ${label}: ${model} ${res.status}`);
        if (res.status === 429 || res.status === 503) await sleep(3000);
        continue;
      }
      const json = await res.json();
      const text = json?.candidates?.[0]?.content?.parts?.map((p) => p.text ?? '').join('') ?? '';
      const parsed = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
      if (!isValid(parsed)) throw new Error('doğrulamadan geçemedi');
      console.log(`✨ ${label}: ${model}`);
      return parsed;
    } catch (e) {
      console.warn(`⚠️ ${label}: ${model} hatası: ${e.message}`);
      await sleep(1500);
    }
  }
  return null;
}

const selectionPrompt = `
Sen İslam ilimlerinde uzman bir editörsün. Bir namaz uygulaması için bugünün içeriğini SEÇECEKSİN.
Metin YAZMA: yalnızca referans ver. Metinler resmi kaynaklardan otomatik çekilecek.

- verse: kalbe huzur, şifa veya umut veren bir ayet (sure ve ayet numarası).
- dua: Kur'an'da geçen bir dua ayeti (ör. "Rabbenâ ..." ile başlayanlar; sure ve ayet numarası).
- hadith: Sahîh-i Buhârî ("bukhari") veya Sahîh-i Müslim ("muslim") içinden kısa, bilinen bir hadis.
  Numara, fawazahmed0/hadith-api'deki hadis numarasıdır.
- Her gün farklı içerik seç; aşağıdaki şablondaki 0 değerlerini kendi seçiminle doldur.
- message: İslam irfanından beslenen, samimi, 1-2 cümlelik Türkçe bir nasihat. Klişe motivasyon cümlesi, ayet veya hadis alıntısı YOK.
${isFriday ? '- Bugün Cuma: Cuma, salavat, Kehf suresi ve dua temalarını gözet.' : ''}
Tarih: ${now.toISOString().slice(0, 10)}

SADECE şu JSON'u döndür:
{"verse":{"surahNumber":0,"verseNumber":0},"dua":{"surahNumber":0,"verseNumber":0},"hadith":{"collection":"bukhari veya muslim","number":0},"message":"..."}
`;

function isValidSelection(s) {
  return (
    s && typeof s === 'object' &&
    Number.isInteger(s.verse?.surahNumber) && Number.isInteger(s.verse?.verseNumber) &&
    Number.isInteger(s.dua?.surahNumber) && Number.isInteger(s.dua?.verseNumber) &&
    HADITH_COLLECTIONS.includes(s.hadith?.collection) && Number.isInteger(s.hadith?.number) &&
    typeof s.message === 'string' && s.message.trim().length >= 20
  );
}

function translationPrompt(message, duaEnglish, hadithEnglish, hadithLanguages) {
  return `Translate content for a Muslim prayer app. Return ONLY JSON of the form
{"<lang>": {"message": "...", "duaTitle": "..."${hadithLanguages.length ? ', "hadith": "..."' : ''}}, ...}
with exactly these language codes: ${APP_LANGUAGES.join(', ')}.

- "message": translate this Turkish message faithfully and naturally (for "tr" copy it unchanged): ${JSON.stringify(message)}
- "duaTitle": a short title (max 6 words) for this Quranic supplication, e.g. "Supplication for Forgiveness"; use the language's word for personal supplication (dua), not ritual prayer: ${JSON.stringify(duaEnglish)}
${hadithLanguages.length ? `- "hadith": ONLY for ${hadithLanguages.join(', ')}: a faithful, reverent translation of this hadith, keeping the narrator and the ﷺ sign; no commentary: ${JSON.stringify(hadithEnglish)}` : ''}
Use established Islamic terminology and the usual form of "Allah" in each language. No markdown.`;
}

function isValidTranslations(t, hadithLanguages) {
  return (
    t && typeof t === 'object' &&
    APP_LANGUAGES.every((l) => typeof t[l]?.message === 'string' && t[l].message.trim() && typeof t[l]?.duaTitle === 'string' && t[l].duaTitle.trim()) &&
    hadithLanguages.every((l) => typeof t[l]?.hadith === 'string' && t[l].hadith.trim())
  );
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

async function main() {
  console.log(`[${now.toISOString()}] Günlük içerik üretimi başlıyor...`);

  const selection = await askGemini(selectionPrompt, isValidSelection, 'seçim');

  let verse = selection && (await fetchVerifiedVerse(selection.verse.surahNumber, selection.verse.verseNumber));
  if (!verse) verse = await fetchVerifiedVerse(...pick(FALLBACK_VERSE_REFS));

  let dua = selection && (await fetchVerifiedVerse(selection.dua.surahNumber, selection.dua.verseNumber));
  if (!dua) dua = await fetchVerifiedVerse(...pick(FALLBACK_DUA_REFS));

  let hadith = selection && (await fetchVerifiedHadith(selection.hadith.collection, selection.hadith.number));
  if (!hadith) hadith = await fetchVerifiedHadith(...pick(FALLBACK_HADITH_REFS));

  const message = selection?.message?.trim() || (isFriday ? FRIDAY_MESSAGE : pick(FALLBACK_MESSAGES));

  console.log(`📖 Ayet: ${verse ? `${verse.surahNumber}:${verse.verseNumber}` : 'yok'} | 🤲 Dua: ${dua ? `${dua.surahNumber}:${dua.verseNumber}` : 'yok'} | 📜 Hadis: ${hadith ? `${hadith.collection} ${hadith.number}` : 'yok'}`);

  const hadithLanguages = hadith ? APP_LANGUAGES.filter((l) => !hadith.translations[l]) : [];
  const translations = await askGemini(
    translationPrompt(message, dua?.translations.en ?? '', hadith?.translations.en ?? '', hadithLanguages),
    (t) => isValidTranslations(t, hadithLanguages),
    'çeviri'
  );

  const dailyMessage = { tr: message };
  const duaTitles = {};
  if (translations) {
    for (const lang of APP_LANGUAGES) {
      if (lang !== 'tr') dailyMessage[lang] = translations[lang].message.trim();
      duaTitles[lang] = translations[lang].duaTitle.trim();
      if (hadith && hadithLanguages.includes(lang)) {
        hadith.translations[lang] = translations[lang].hadith.trim();
        (hadith.machineTranslated ??= []).push(lang);
      }
    }
  } else {
    console.warn('⚠️ Çeviri alınamadı; uygulama eksik dillerde İngilizce/yerel içeriği gösterecek.');
  }

  const contentData = {
    version: '2.0.0',
    updatedAt: now.toISOString(),
    date: now.toISOString().slice(0, 10),
    isFriday,
    ...(verse && { verifiedVerse: verse }),
    ...(dua && { verifiedDua: { ...dua, titles: duaTitles } }),
    ...(hadith && { verifiedHadith: hadith }),
    dailyMessage,
  };

  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  fs.writeFileSync(outputPath, JSON.stringify(contentData, null, 2), 'utf-8');
  console.log(`✅ İçerik yazıldı: ${outputPath}`);
}

main().catch((err) => {
  console.error('Kritik Hata:', err);
  process.exit(1);
});
